const SEC = Object.fromEntries(TREE.map(s=>[s.id,s]));
const MS = {}; TREE.forEach(s=>s.ms.forEach(m=>{MS[m.id]=m; m.sec=s.id;}));

// ---------- Fiches détaillées : comment faire, repères, erreur fréquente, critère de validation ----------
const DETAILS = {
  st_bail30:{how:["Pose les mains à environ 30 cm du mur, largeur d'épaules, doigts bien écartés.","Monte en équilibre par une fente, sans chercher à tenir.","Dès que tu bascules, avance une main d'un quart de tour et laisse les jambes redescendre l'une après l'autre sur le côté, comme une roue.","Répète des deux côtés jusqu'à ce que le geste soit automatique."],cue:["Bras tendus du début à la fin.","Le regard reste au sol, entre les mains."],err:"Plier les bras, ou se laisser tomber sur le dos au lieu de pivoter.",ok:"Tu sors en roue 5 fois de suite sans hésiter, en arrivant sur les pieds."},
  lo_frog:{how:["Accroupi, mains au sol largeur d'épaules, doigts écartés.","Grenouille : cale l'intérieur des genoux contre l'extérieur des coudes, bras fléchis, puis penche-toi vers l'avant jusqu'à ce que les pieds décollent.","Corbeau : même chose avec les genoux posés plus haut, sur l'arrière des bras, et les hanches plus hautes."],cue:["Regarde devant tes mains, pas tes pieds.","Ce sont les doigts qui freinent la bascule vers l'avant."],err:"Sauter dans la position au lieu de s'y pencher lentement.",ok:"Tu tiens chaque position 10 s sans que les pieds retouchent le sol."},
  st_split:{how:["Monte ventre face au mur en marchant les pieds le long du mur, mains à 10–20 cm de celui-ci.","Écarte une jambe loin du mur ; l'autre pied reste posé dessus.","Appuie dans les doigts jusqu'à sentir le pied quitter le mur de lui-même.","Tiens, puis repose le pied en douceur."],cue:["Épaules poussées vers le haut, oreilles cachées par les bras.","Le pied quitte le mur parce que tu es en équilibre, pas parce que tu le repousses."],err:"Donner une impulsion sur le mur : tu pars alors à la renverse.",ok:"5 s pied décollé, 3 fois dans la même séance."},
  st_bailc2w:{how:["Monte ventre face au mur, mains à une largeur de main du mur.","Déplace une main sur le côté en tournant le buste.","Laisse les jambes descendre l'une après l'autre du même côté.","Entraîne les deux côtés."],cue:["Choisis ton côté de sortie avant de monter."],err:"Redescendre en marchant le long du mur par habitude : la sortie doit devenir un réflexe.",ok:"Tu sors des deux côtés sans réfléchir, même fatigué."},
  b1_free5:{how:["Loin du mur, monte par une fente, jambe arrière tendue.","Arrête-toi jambes ouvertes en ciseaux, sans chercher à les réunir.","Corrige avec les mains : appuie dans les doigts si tu pars vers l'avant, dans le talon de la main si tu reviens.","Si tu dépasses, sors en roue."],cue:["La même montée à chaque essai : même distance, même élan.","Mieux vaut monter un peu court que trop fort."],err:"Enchaîner des dizaines d'essais bâclés. Fais des séries courtes, reposé.",ok:"15 s au chrono, sans marcher sur les mains (paliers à 5 et 10 s)."},
  b2_str15:{how:["Monte en ciseaux, stabilise, puis réunis lentement les jambes.","Serre les jambes l'une contre l'autre, pointes tendues.","Repousse le sol pour te grandir au maximum."],cue:["Côtes rentrées, bassin basculé : pas de dos creux.","Regard entre les mains."],err:"Réunir les jambes trop vite et perdre l'équilibre que tu venais de trouver.",ok:"15 s jambes serrées, corps aligné."},
  in_holds:{how:["Depuis l'équilibre droit, prends une forme et tiens-la : jambes écartées, ciseaux, groupé.","Commence par les jambes écartées, la plus stable.","Vise 5 à 10 s par forme."],cue:["Quand les jambes partent d'un côté, les épaules compensent de l'autre."],err:"Changer de forme avant d'avoir stabilisé la précédente.",ok:"Tu tiens chaque forme du niveau 1 environ 10 s."},
  in_changes:{how:["En équilibre, passe lentement d'une forme à l'autre : droit, écarté, droit, groupé.","Chaque transition dure 2 à 3 s.","Marque un arrêt net dans chaque forme."],cue:["Mouvement lent et continu, sans à-coup.","Les mains anticipent le déplacement des jambes."],err:"Accélérer pour « passer » la transition.",ok:"Tu enchaînes 3 changements de forme sur une seule montée."},
  in_tuck:{how:["Depuis l'équilibre droit, plie les genoux et descends-les lentement vers la poitrine.","Arrête quand les cuisses sont à l'horizontale, genoux à hauteur des hanches.","Laisse les épaules avancer légèrement au-dessus des doigts pour compenser."],cue:["Dos arrondi, bassin au-dessus des épaules.","Talons près des fesses."],err:"Garder les épaules fixes : le poids des genoux te ramène alors au sol.",ok:"10 s, cuisses à l'horizontale."},
  in_str40:{how:["Travaille en séries : 3 à 5 tenues proches de ton maximum, 2 min de repos.","Ajoute des tenues poitrine face au mur de 45 à 60 s pour l'endurance des épaules.","Respire lentement pendant la tenue."],cue:["Repousse le sol en continu, épaules hautes.","Corrige petit et tôt."],err:"Retenir sa respiration : tu tiens 20 s puis tout lâche d'un coup.",ok:"40 s au chrono."},
  in_str60:{how:["Même travail, en visant des tenues de 45 s et plus.","Garde une à deux séances par semaine pour les tenues longues.","Arrête la série quand la ligne se dégrade."],cue:["Économise-toi : le moins de corrections possible."],err:"Tenter le record à chaque séance.",ok:"60 s au chrono."},
  in_7s:{how:["Depuis l'équilibre droit, descends une jambe tendue vers l'avant jusqu'à l'horizontale.","L'autre jambe reste verticale.","Les épaules avancent un peu pour compenser."],cue:["Jambe basse tendue, parallèle au sol.","Bassin au-dessus des épaules."],err:"Plier la jambe ou cambrer pour compenser.",ok:"5 s de chaque côté."},
  in_7d:{how:["Depuis l'équilibre droit, descends les deux jambes serrées et tendues vers l'avant.","Arrête à l'horizontale.","Avance franchement les épaules au-dessus des doigts."],cue:["Dos plat ou arrondi, jamais creusé.","Appuie fort dans les doigts."],err:"Descendre trop vite : la bascule arrive d'un coup.",ok:"5 s jambes à l'horizontale."},
  in_toes:{how:["En équilibre droit, rentre lentement le menton vers la poitrine.","Amène la tête entre les bras et regarde tes orteils.","Les premières fois, fais-le près d'un mur."],cue:["Tu t'équilibres à la pression dans les mains, plus à la vue.","Les épaules s'ouvrent davantage."],err:"Bouger la tête brusquement.",ok:"15 s tête rentrée."},
  in_toes7:{how:["Installe d'abord le 7 à deux jambes.","Rentre ensuite la tête et regarde tes orteils.","Ressors la tête avant de remonter les jambes."],cue:["Un seul changement à la fois."],err:"Tout faire en même temps.",ok:"5 s en 7, tête rentrée."},
  oa_flaghoriz:{how:["En équilibre jambes écartées, incline lentement les jambes sur le côté : une jambe descend, l'autre monte.","Le bassin se décale pour faire contrepoids et le poids se concentre sur une main.","Arrête quand la jambe basse passe sous l'horizontale, tiens, reviens."],cue:["Les deux bras restent tendus.","Le bassin s'incline sans vriller."],err:"Tourner le bassin au lieu de l'incliner.",ok:"10 s sous l'horizontale, de chaque côté."},
  oa_flagfloor:{how:["Même mouvement que le drapeau, poussé plus loin.","Descends la jambe basse jusqu'à effleurer le sol.","Remonte sans élan."],cue:["Contrôle la descente : le pied ne tombe pas."],err:"Poser du poids sur le pied.",ok:"Tu touches le sol et tu remontes, des deux côtés."},
  in_mexican:{how:["Échauffe longuement les épaules et le dos.","En équilibre, laisse les jambes partir derrière toi en cambrant.","Pousse la poitrine vers l'avant, entre les bras, pour faire contrepoids."],cue:["La cambrure vient du haut du dos et des épaules, pas seulement des lombaires."],err:"Forcer sans avoir la mobilité d'épaules nécessaire.",ok:"Tu tiens la forme quelques secondes et tu reviens à l'équilibre droit."},
  in_hspu:{how:["Commence contre un mur.","Descends en 3 s en amenant la tête en avant des mains : tête et mains forment un triangle.","Repousse jusqu'aux bras tendus."],cue:["Coudes vers l'arrière, pas écartés.","Corps gainé du début à la fin."],err:"Laisser tomber la tête sur le sol.",ok:"3 répétitions complètes d'affilée."},
  fd_plank:{how:["Mains sous les épaules, bras tendus, doigts écartés.","Serre les fessiers et rentre le ventre : le bas du dos ne se creuse pas.","Repousse le sol pour écarter les omoplates."],cue:["Une ligne droite de la tête aux talons."],err:"Laisser tomber le bassin ou le monter en pic.",ok:"30 s sans que le bassin bouge."},
  fd_roue:{how:["Debout, bras en l'air, regarde le point où tu poseras les mains.","Pose une main puis l'autre sur une ligne, jambes qui passent écartées par-dessus.","Retombe sur un pied puis l'autre, face au point de départ."],cue:["Les jambes passent au-dessus, pas sur le côté.","Commence petit : jambes basses, puis de plus en plus hautes."],err:"Avoir peur de lâcher une main : c'est justement ce geste qui te sauvera.",ok:"5 roues de chaque côté, retombée sur les pieds."},
  fd_push:{how:["Mains un peu plus larges que les épaules, corps gainé.","Descends jusqu'à frôler le sol avec la poitrine, coudes à 45° du corps.","Remonte en poussant fort, bras tendus en haut."],cue:["Le corps monte et descend d'un bloc."],err:"Creuser le dos ou faire des demi-pompes.",ok:"20 pompes complètes d'affilée."},
  fd_c2w:{how:["Mets-toi en position de pompe, pieds contre le mur.","Monte les pieds le long du mur en rapprochant les mains, petit pas par petit pas.","Arrête-toi mains à une main du mur, corps vertical, poitrine face au mur.","Redescends de la même façon, sans te jeter."],cue:["Pousse le sol : les épaules montent vers les oreilles.","Ventre rentré, regard entre les mains."],err:"Mains trop loin du mur : le dos se creuse en banane.",ok:"60 s tenues, corps aligné."},
  fd_dips:{how:["En appui sur les barres, bras tendus, épaules basses.","Descends en pliant les coudes jusqu'à 90°, buste légèrement penché.","Remonte jusqu'aux bras tendus."],cue:["Épaules loin des oreilles en bas."],err:"Descendre trop bas les premières fois : ça tire sur l'avant des épaules.",ok:"10 dips complets d'affilée."},
  pl_lean:{how:["Position de pompe, bras tendus, doigts vers l'extérieur ou sur parallettes.","Avance les épaules loin devant les mains, sur la pointe des pieds.","Écarte les omoplates et rentre le bassin."],cue:["Épaules 10 à 15 cm devant les mains, puis plus.","Coudes verrouillés, creux du coude tourné vers l'avant."],err:"Plier les coudes pour avancer : c'est l'épaule qui avance, pas le bras qui se plie.",ok:"30 s, épaules nettement devant les mains."},
  oa_strad30:{how:["Monte, ouvre les jambes en grand écart facial, pointes tendues.","Le bassin reste au-dessus des épaules, les jambes larges stabilisent."],cue:["Pousse le sol, épaules aux oreilles.","Jambes actives, pas posées."],err:"Laisser les jambes tomber vers l'avant : le dos se creuse.",ok:"30 s libres, jambes écartées, sans pas de mains."},
  oa_wall:{how:["Dos au mur, jambes écartées, talons au mur.","Glisse le poids sur une main, puis retire l'autre : épaule poussée vers l'oreille, bassin au-dessus de la main."],cue:["Bras verrouillé, épaule haute.","Côté faible d'abord."],err:"Laisser l'épaule s'affaisser : c'est elle qui porte.",ok:"30 s sur chaque bras, épaule haute."},
  oa_lift:{how:["Depuis l'appui bras tendu, allège encore la main libre.","Décolle-la de quelques centimètres, tiens 2 s, repose-la sans à-coup."],cue:["Les doigts de la main d'appui corrigent.","Le bassin ne bouge pas quand la main part."],err:"Lancer la main : elle se soulève parce qu'elle ne porte plus rien.",ok:"5 décollages de 2 s, de chaque côté."},
  oa_oahs10:{how:["Même travail que pour 5 s, en essais courts et propres.","Le côté faible reçoit autant d'essais que le fort, et passe en premier."],cue:["Calme, petites corrections des doigts."],err:"Ne travailler que le bon côté.",ok:"10 s sur chaque bras."},
  pl_ppp:{how:["Position de pompe, mains au niveau des hanches, doigts vers l'extérieur.","Descends en gardant les épaules devant les mains, puis repousse en écartant les omoplates."],cue:["Coudes contre le corps.","Le corps reste gainé, fesses serrées."],err:"Reculer les épaules en descendant : on perd l'avancée qui fait le travail.",ok:"10 pompes propres, épaules toujours devant les mains."},
  pl_1leg:{how:["Depuis la frog planche, tends une jambe derrière toi.","Elle reste dans l'alignement du corps, la hanche ne tombe pas."],cue:["Épaules devant, bassin rétroversé.","Alterne la jambe à chaque série."],err:"Laisser la hanche de la jambe tendue tomber.",ok:"10 s sur chaque jambe."},
  pl_tuck:{how:["Depuis le lean, décolle les pieds en ramenant les genoux contre la poitrine.","Dos rond, omoplates écartées et abaissées.","Hanches qui montent presque à hauteur des épaules."],cue:["Bras tendus, verrouillés.","Les épaules restent devant les mains, abaissées, loin des oreilles."],err:"S'accroupir sur les bras : pieds trop bas, hanches tombantes.",ok:"20 s, bras tendus, pieds décollés."},
  pl_adv:{how:["Depuis le tuck, éloigne les genoux de la poitrine.","Dos plat : les hanches montent à hauteur des épaules."],cue:["Bassin rétroversé, ventre serré.","Épaules encore plus en avant qu'en tuck."],err:"Garder le dos rond : ce n'est plus un advanced tuck.",ok:"15 s, dos plat, hanches à hauteur des épaules."},
  pl_frog:{how:["Depuis l'advanced tuck, ouvre les genoux sur les côtés.","Pieds relevés derrière, jambes fléchies et écartées."],cue:["Les hanches ne tombent pas quand les jambes s'ouvrent."],err:"Plier les bras pour compenser.",ok:"10 s, dos plat, bras tendus."},
  pl_pike:{how:["Tends les jambes écartées, hanches encore un peu fléchies.","Étape de transition : chaque séance, ouvre un peu plus les hanches."],cue:["Bassin rétroversé : ne casse pas la ligne au bassin."],err:"Rester carpé longtemps : vise vite la ligne droite.",ok:"15 s, jambes tendues."},
  pl_straddle:{how:["Corps à l'horizontale, jambes tendues et écartées.","Épaules loin devant les mains, omoplates écartées et abaissées."],cue:["Bassin rétroversé, fessiers serrés.","Coudes verrouillés."],err:"Creuser le dos ou plier les bras.",ok:"10 s, corps horizontal, jambes tendues."},
  pl_full:{how:["Depuis la straddle, resserre les jambes jusqu'à la full.","Tout le corps horizontal, d'un bloc."],cue:["Épaules très en avant, bassin rétroversé."],err:"Hanches qui tombent sous la ligne des épaules : le bassin reste au niveau, quitte à revenir en straddle.",ok:"10 s, jambes serrées, corps horizontal."},
  oa_shift:{how:["En équilibre jambes écartées, envoie le bassin au-dessus de la main d'appui.","L'épaule d'appui reste empilée au-dessus du poignet : elle ne se balade pas.","L'autre main s'allège jusqu'à ne presque plus appuyer, puis reviens au centre et change de côté."],cue:["Main d'appui légèrement tournée vers l'extérieur, doigts en griffe.","Lent : 2 à 3 s par transfert."],err:"Déplacer les épaules au lieu du bassin.",ok:"5 transferts propres de chaque côté, sans casser la ligne."},
  oa_finger:{how:["Transfère le poids sur un bras.","Soulève la paume de l'autre main : seuls les doigts touchent le sol."],cue:["Épaule d'appui poussée vers l'oreille.","Bassin au-dessus de la main d'appui."],err:"S'appuyer sur les doigts plus qu'on ne le croit.",ok:"20 s de chaque côté."},
  oa_strarm:{how:["Même transfert, mais éloigne la main libre sur le côté, bras tendu.","Elle ne garde qu'un contact léger avec le sol.","Éloigne-la un peu plus à chaque séance."],cue:["Plus la main est loin, moins elle peut t'aider."],err:"Plier le bras libre pour reprendre appui.",ok:"15 s de chaque côté (note le côté travaillé)."},
  oa_oahs:{how:["Main d'appui tournée d'environ 45° vers l'extérieur.","Depuis l'appui léger, décolle la main libre de quelques centimètres, puis tends ce bras sur le côté comme un balancier.","Garde les jambes écartées pour l'équilibre latéral.","Multiplie les essais courts et propres."],cue:["Repousse le sol, épaule haute.","Regard fixe."],err:"Lancer la main en l'air. Elle se soulève parce que le poids n'y est plus, pas l'inverse.",ok:"5 s main décollée."},
  pr_straddle:{how:["Debout jambes très écartées, mains au sol près des pieds, bras tendus.","Avance les épaules au-dessus des doigts et monte sur la pointe des pieds.","Soulève le bassin au-dessus des épaules : les pieds décollent sans saut.","Ouvre les jambes sur les côtés, puis réunis-les en haut."],cue:["Bras tendus tout du long.","C'est le bassin qui monte, pas les pieds qui sautent."],err:"Sauter. Travaille plutôt la descente lente depuis l'équilibre.",ok:"3 montées propres d'affilée, sans saut."},
  pr_pike:{how:["Même principe, mains posées devant les pieds joints.","Avance davantage les épaules.","Les jambes, tendues et serrées, montent par l'avant."],cue:["Ventre contre les cuisses au départ."],err:"Écarter les jambes en cours de montée.",ok:"Une montée jambes serrées et tendues."},
  pr_negS:{how:["Monte en équilibre jambes écartées.","Avance les épaules et laisse le bassin descendre derrière, jambes écartées tendues.","Compte 5 secondes jusqu'aux pieds, pose-les sans bruit."],cue:["Épaules devant les mains tout du long.","Les jambes restent larges et actives."],err:"Plier les bras pour freiner : c'est l'épaule qui travaille, pas le coude.",ok:"3 descentes de 5 s, pieds posés en douceur."},
  pr_stradL:{how:["Assis jambes écartées tendues, mains entre les jambes (sur parallettes c'est plus facile).","Pousse le sol, abaisse les épaules et décolle les fesses et les talons."],cue:["Bras verrouillés, épaules basses.","Pointes tendues, genoux tendus."],err:"Se pencher en arrière : le buste reste au-dessus des mains.",ok:"10 s, fesses et talons décollés."},
  pr_lsit:{how:["Mains au sol ou sur parallettes à côté des hanches, bras tendus.","Pousse le sol, abaisse les épaules, décolle fesses et talons, jambes serrées tendues."],cue:["Genoux verrouillés, pointes tendues.","Épaules loin des oreilles."],err:"Laisser les jambes tomber sous l'horizontale ou plier les genoux.",ok:"15 s, jambes à l'horizontale."},
  pr_lsitHs:{how:["Depuis l'équerre, avance les épaules au-dessus des mains et arrondis le dos.","Le bassin monte derrière, les jambes serrées passent sous puis au-dessus de la ligne des épaules (forte compression).","Termine comme une montée en force jambes serrées, et ouvre jusqu'à l'équilibre."],cue:["Les pieds ne touchent jamais le sol.","Compression maximale : genoux près du visage."],err:"Donner un coup de reins : le passage doit être lent et continu.",ok:"Une montée complète et lente, de l'équerre à l'équilibre."},
  pr_elev:{how:["Mains sur les parallettes, pieds sur une chaise derrière toi, jambes écartées.","Avance les épaules loin devant les mains, arrondis le dos, laisse le bassin monter.","Les pieds quittent la chaise sans saut, et tu montes jusqu'à l'équilibre (dos au mur au début si besoin)."],cue:["Épaules devant, bras verrouillés.","Pousse le sol, ne saute pas."],err:"Donner une impulsion avec les pieds : la chaise sert à commencer plus haut, pas à sauter.",ok:"3 montées propres, sans impulsion."},
  oa_tuckflag:{how:["Genoux groupés, incline-les sur le côté.","Le bassin suit, le poids va sur une main."],cue:["Bras tendus."],err:"Vriller le bassin.",ok:"5 s par côté."},
  oa_shrug:{how:["Un bras au mur, bras verrouillé.","L'épaule descend, puis repousse vers l'oreille."],cue:["Lent, sans plier le coude."],err:"Plier le coude.",ok:"8 par côté."},
  oa_sidehold:{how:["Transfert complet vers la main d'appui.","Abaisse légèrement la hanche de ce côté et tiens."],cue:["Épaule au-dessus du poignet."],err:"L'épaule dépasse la main.",ok:"20 s par côté."},
  oa_finger3:{how:["Depuis la tente, retire l'annulaire et l'auriculaire."],cue:["Les doigts corrigent, ils ne portent pas."],err:"Appuyer fort sur les doigts.",ok:"15 s par côté."},
  oa_finger2:{how:["Ne garde que le pouce et l'index."],cue:["Contact léger."],err:"Le bassin revient au centre.",ok:"15 s par côté."},
  oa_finger1:{how:["Ne garde que l'index, puis plie-le jusqu'à ce que la main flotte."],cue:["Calme, peu de corrections."],err:"Le doigt devient une béquille.",ok:"10 s par côté."},
  oa_oahsw:{how:["Toutes les étapes refaites côté faible."],cue:["Le côté faible passe en premier."],err:"Ne s'entraîner que sur le bon côté.",ok:"5 s sur chaque bras, la même séance."},
  pl_lean2:{how:["Depuis le lean, avance jusqu'à avoir les épaules au-dessus des doigts.","Pousse le sol, rentre le bassin."],cue:["Coudes verrouillés."],err:"Lever les fesses pour gagner de l'avancée.",ok:"20 s, épaules au-delà des doigts."},
  pl_tuckP:{how:["Lean sur parallettes, genoux à la poitrine.","Décolle en avançant les épaules."],cue:["Dos rond, omoplates écartées."],err:"Sauter pour décoller.",ok:"10 s, pieds décollés."},
  pl_tuckPu:{how:["En tuck, plie les coudes et descends.","Repousse sans poser les pieds."],cue:["Coudes près du corps."],err:"Reculer les épaules.",ok:"5 répétitions sans toucher le sol."},
  pl_tuckO:{how:["Depuis le tuck, éloigne les genoux jusqu'à les avoir sous les hanches.","Commence à aplatir le dos."],cue:["Bassin rétroversé."],err:"Hanches qui tombent.",ok:"15 s, hanches à 90°."},
  pl_strBand:{how:["Sécurité : porte fermée à clé, élastique vérifié avant chaque séance, sortie pieds au sol.","Élastique épais fixé en hauteur (ancrage de porte), passé sous les hanches.","Jambes tendues et écartées."],cue:["Corps horizontal."],err:"S'avachir dans l'élastique.",ok:"15 s, ligne propre."},
  pl_strBandL:{how:["Même chose avec un élastique fin."],cue:["Épaules encore plus en avant."],err:"Plier les bras.",ok:"10 s, élastique presque relâché."},
  pl_strNar:{how:["Depuis la straddle, rapproche les pieds."],cue:["Fessiers serrés."],err:"Hanches qui fléchissent.",ok:"8 s, pieds à une largeur d'épaules."},
  pl_half:{how:["Jambes serrées, genoux pliés, hanches tendues."],cue:["Genoux plus bas que les hanches."],err:"Hanches fléchies : ce serait un tuck.",ok:"8 s."},
  pl_fullBand:{how:["Élastique léger aux hanches, jambes serrées."],cue:["Corps d'un bloc."],err:"Creuser le dos.",ok:"10 s, élastique fin."},
  pl_fullNeg:{how:["Monte en straddle, resserre les jambes.","Freine la descente des hanches."],cue:["Coudes verrouillés."],err:"Lâcher d'un coup.",ok:"5 descentes de 3 s ou plus."},
  pr_pikeLift:{how:["Jambes serrées tendues, mains à plat à mi-cuisse.","Dos rond, lève les talons 2 s."],cue:["Rotule tirée vers le haut."],err:"Se pencher en arrière.",ok:"10 élévations."},
  pr_stradLift:{how:["Écart large, mains devant le bassin.","Lève les deux pieds, 2 s."],cue:["Pointes tendues."],err:"Plier les genoux.",ok:"10 élévations."},
  pr_vsit:{how:["Équerre écartée sur parallettes.","Avance les épaules, monte les pieds au-dessus des hanches."],cue:["Bras verrouillés."],err:"Basculer le buste en arrière.",ok:"5 s, pieds au-dessus des hanches."},
  pr_wallNeg:{how:["Équilibre poitrine face au mur.","Ouvre les jambes, épaules devant, descends."],cue:["Compression dès que les pieds quittent le mur."],err:"Plier les bras.",ok:"5 descentes de 5 s."},
  pr_elevLow:{how:["Comme la montée pieds sur une chaise, mais pieds sur une marche."],cue:["Le bassin monte, pas les pieds."],err:"Sauter.",ok:"3 montées propres."},
  pr_negP:{how:["Équilibre, ferme les jambes en pike.","Épaules devant, dos rond, descends."],cue:["Ventre vers les cuisses."],err:"Ouvrir les jambes.",ok:"3 descentes de 5 s."},
  pr_halfSt:{how:["Équilibre sur parallettes.","Descends jusqu'à l'équerre écartée, pieds décollés."],cue:["Épaules devant."],err:"Toucher le sol.",ok:"3 descentes de 5 s."},
  pr_tuckUp:{how:["Équerre groupée sur parallettes hautes.","Penche-toi, le bassin monte jusqu'au groupé, puis tends les jambes."],cue:["Genoux au nez."],err:"Coup de reins.",ok:"2 montées lentes."},
  pr_stalPart:{how:["Équerre écartée.","Monte le bassin au-dessus des mains, tiens, reviens."],cue:["Pieds hauts, jamais au sol."],err:"Plier les coudes.",ok:"3 répétitions, 2 s en haut."},
  pr_lsitNeg:{how:["Équilibre, ferme en pike.","Descends jusqu'à l'équerre serrée."],cue:["Compression maximale."],err:"Écarter les jambes.",ok:"3 descentes de 5 s."},
  pr_stalder:{how:["Assis jambes écartées, mains au sol entre les jambes : soulève-toi en équerre.","Bascule le bassin vers l'arrière et le haut en avançant les épaules.","Termine comme une montée en force jambes écartées."],cue:["Les pieds ne touchent jamais le sol."],err:"Plier les bras ou frotter les pieds : sans compression, le bassin ne monte pas.",ok:"Une montée complète depuis l'équerre."},
  lo_elbow:{how:["À genoux, mains au sol, doigts tournés vers l'extérieur ou l'arrière.","Cale les coudes contre le ventre, près des hanches.","Penche-toi vers l'avant et tends les jambes : le corps passe à l'horizontale."],cue:["Corps gainé, comme une planche posée sur un tréteau."],err:"Coudes trop écartés : ils glissent sur les côtés.",ok:"10 s à l'horizontale."},
  lo_croc:{how:["Installe la planche sur les coudes.","Transfère le poids sur un seul coude.","Les deux mains restent au sol : un seul coude est calé dans la hanche, l'autre bras sert d'appui."],cue:["Le coude d'appui est sous le centre du corps."],ok:"5 s de chaque côté."},
  lo_qdr:{how:["Accroupi, cale un coude contre la hanche du même côté.","Pose les deux mains et le côté de la tête au sol.","Bascule le poids sur le coude et décolle les pieds, genoux groupés."],cue:["Trois appuis : les deux mains et la tête."],ok:"5 s pieds décollés."},
};
